<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\RateLimiter;use App\Models\AdminCommandRun;use App\Services\AdminConsole\AdminCommandRegistry;
class AdminConsoleController extends Controller {public function index(){return view('admin.server-console',['runs'=>AdminCommandRun::latest()->limit(30)->get(),'registry'=>AdminCommandRegistry::all()]);}public function store(Request $q){$key='admin-console:'.($q->session()->get('admin_email')?:$q->ip());if(RateLimiter::tooManyAttempts($key,10))return back()->withErrors(['command'=>'Terlalu banyak request. Coba lagi nanti.']);RateLimiter::hit($key,60);try{[$name,$args,$params,$spec]=AdminCommandRegistry::parse($q->validate(['command'=>'required|string|max:500'])['command']);if(($spec['confirm']??false)&&!$q->boolean('confirmed'))return back()->withErrors(['command'=>'Konfirmasi diperlukan untuk command ini.']);AdminCommandRun::create(['command_key'=>$name,'command_label'=>$spec['label'],'command_input'=>$q->command,'command_name'=>$name,'command_arguments'=>$args,'command_options'=>$params,'status'=>'pending','requested_by'=>$q->session()->get('admin_email'),'requested_at'=>now()]);return back()->with('status','Command masuk antrean.');}catch(\Throwable $e){return back()->withErrors(['command'=>$e->getMessage()]);}}public function output(AdminCommandRun $run){return response()->json($run);}}
